import click

class CustomArgument(click.Argument):
    pass

# variant A: separate decorator calls
@click.command()
@click.argument("arg", cls=CustomArgument)
@click.argument("arg2", cls=CustomArgument)
def cli(arg, arg2):
    pass
print("A:", [type(p).__name__ for p in cli.params])

# variant B: reused decorator object
dec = click.argument("arg", cls=CustomArgument)
@click.command()
@dec
def cli2(arg):
    pass
@click.command()
@dec
def cli3(arg):
    pass
print("B:", [type(p).__name__ for p in cli2.params], [type(p).__name__ for p in cli3.params])
EOF

